* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #f8fafc; color: #0f172a; min-height: 100vh;
}
.topbar {
  background: #0f172a; color: #fff; padding: 14px 18px;
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;
}
.brand { font-weight: 800; font-size: 16px; }
#addForm { display: flex; gap: 8px; }
#newTask {
  padding: 8px 12px; border-radius: 8px; border: 1px solid #334155;
  background: #1e293b; color: #fff; font-size: 13px; width: 220px;
}
.btn { background: #f59e0b; color: #0f172a; border: 0; padding: 8px 14px; border-radius: 8px; font-weight: 700; cursor: pointer; }
.hint { font-size: 12px; color: #94a3b8; padding: 12px 18px 0; }
.board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; padding: 18px; }
.column { background: #e2e8f0; border-radius: 14px; padding: 12px; min-height: 260px; }
.column h3 {
  font-size: 12px; text-transform: uppercase; letter-spacing: .05em;
  display: flex; align-items: center; gap: 8px; margin-bottom: 10px;
}
.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.column em { font-style: normal; background: #fff; border-radius: 99px; padding: 1px 8px; font-size: 11px; margin-left: auto; }
.card {
  background: #fff; border-radius: 10px; padding: 10px; margin-bottom: 10px;
  box-shadow: 0 1px 3px rgba(0, 0, 0, .1); cursor: grab; border: 1px solid #f1f5f9;
}
.card:active { cursor: grabbing; }
.card p { font-size: 13px; font-weight: 600; margin-bottom: 6px; }
.tag { font-size: 10px; background: #fef3c7; color: #92400e; border-radius: 99px; padding: 2px 8px; }

const columns = [
  { id: 'todo', title: 'To Do', color: '#f59e0b' },
  { id: 'doing', title: 'In Progress', color: '#3b82f6' },
  { id: 'done', title: 'Done', color: '#22c55e' }
]
let tasks = [
  { id: 1, col: 'todo', text: 'Riset kebutuhan klien', tag: 'Analisis' },
  { id: 2, col: 'todo', text: 'Wireframe halaman utama', tag: 'Desain' },
  { id: 3, col: 'doing', text: 'Kembangkan API login', tag: 'Backend' },
  { id: 4, col: 'doing', text: 'Perbaiki bug responsif', tag: 'Frontend' },
  { id: 5, col: 'done', text: 'Desain logo brand', tag: 'Desain' }
]
let seq = 6
let dragging = null

const board = document.getElementById('board')

function render() {
  board.innerHTML = ''
  columns.forEach((col) => {
    const colEl = document.createElement('section')
    colEl.className = 'column'
    colEl.dataset.col = col.id
    colEl.innerHTML = `<h3><span class="dot" style="background:${col.color}"></span>${col.title} <em>${tasks.filter((t) => t.col === col.id).length}</em></h3>`
    tasks.filter((t) => t.col === col.id).forEach((task) => {
      const card = document.createElement('article')
      card.className = 'card'
      card.draggable = true
      card.dataset.id = task.id
      card.innerHTML = `<p>${task.text}</p><span class="tag">${task.tag}</span>`
      card.addEventListener('dragstart', () => { dragging = task.id })
      card.addEventListener('click', () => cycle(task.id))
      colEl.appendChild(card)
    })
    colEl.addEventListener('dragover', (e) => e.preventDefault())
    colEl.addEventListener('drop', () => { if (dragging) moveTo(dragging, col.id) })
    board.appendChild(colEl)
  })
}

function moveTo(id, col) {
  tasks = tasks.map((t) => (t.id === id ? { ...t, col } : t))
  dragging = null
  render()
}
function cycle(id) {
  const order = ['todo', 'doing', 'done']
  const t = tasks.find((x) => x.id === id)
  const next = order[(order.indexOf(t.col) + 1) % order.length]
  moveTo(id, next)
}
function addTask() {
  const text = document.getElementById('newTask').value.trim()
  if (!text) return
  tasks.push({ id: seq++, col: 'todo', text, tag: 'Baru' })
  document.getElementById('newTask').value = ''
  render()
}
document.getElementById('addForm').addEventListener('submit', (e) => { e.preventDefault(); addTask() })
render()
